<?php
$rows=$db->query('SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll();echo '<div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Summary</th><th>IP</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['user_name']?:'System').'</td><td>'.e($r['action']).'</td><td>'.e($r['entity']).' '.e($r['entity_id']).'</td><td>'.e($r['summary']).'</td><td>'.e($r['ip_address']).'</td></tr>';echo '</tbody></table></div>';
